template <typename It>
std::size_t count_steps(It first, It last) {
    if constexpr (std::random_access_iterator<It>) {
        return static_cast<std::size_t>(last - first);
    } else {
        std::size_t n = 0;
        for (; first != last; ++first) ++n;
        return n;
    }
}

