std::size_t count_words(std::string_view text) {
    std::size_t words = 0, pos = 0;
    while ((pos = text.find_first_not_of(' ', pos)) != std::string_view::npos) {
        ++words;
        pos = text.find(' ', pos);
        if (pos == std::string_view::npos) break;
    }
    return words;
}

